def transform(grid):
    h,w=len(grid),len(grid[0])
    for c in range(w):
        if all(row[c]==grid[0][c] for row in grid) and c>0 and w-c-1==c:
            a=[row[:c] for row in grid]; b=[row[c+1:] for row in grid]
            if any(9 in row for row in b):
                return [[2 if y==0 else 0 for y in br] for br in b]
            return [[2 if x!=0 and y!=0 else 0 for x,y in zip(ar,br)] for ar,br in zip(a,b)]
    for r in range(h):
        if all(x==grid[r][0] for x in grid[r]) and r>0 and h-r-1==r:
